function [p] = albedo_pressure(r, sun_rel, p_sun)
%ALBEDO_PRESSURE  The albedo pressure [N/m^2] at the inertial position r, the Sun at sun_rel from the satellite, p_sun the Sun's
%   pressure at the satellite.
%   r: real[m][3] (passed in m)
%   sun_rel: real[m][3] (passed in m)
%   p_sun: real[Pa] (passed in kg/(m s^2))
%   returns p: real[Pa] (passed in kg/(m s^2))
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    p = 0;
    rn = sqrt(r(1)*r(1) + r(2)*r(2) + r(3)*r(3));
    vf = ((6378137 / rn) * (6378137 / rn));
    cz0 = asils.pc.dot_(asils.models.facets.unit_or_zero(((sun_rel + r) * 1)), (r * (1 / rn)));
    cz = asils.pc.choose((cz0 > 0), cz0, 0);
    p = (((0.3 * p_sun) * vf) * cz);
end
